#!/usr/bin/env python3
# Some portions generated by Codex. Run only after candidate freeze/handoff; no JVM work.
import pathlib,hashlib,json,shutil
r=pathlib.Path(__file__).resolve().parents[3];d=pathlib.Path(__file__).resolve().parent;old=d.parent/'depth-workbench'
source=d.parent/'resource-holder/candidate-layer';dest=d/'resource-layer'
# Existing freeze may be reused only if every byte matches.
files=sorted(source.rglob('*.class'));assert len(files)==105
assert all(p.name.startswith('LmdbSailStore') for p in files)
if dest.exists():
 assert {str(p.relative_to(source)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files} == {str(p.relative_to(dest)):hashlib.sha256(p.read_bytes()).hexdigest() for p in dest.rglob('*.class')}
else:shutil.copytree(source,dest)
manifest={str(p.relative_to(dest)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(dest.rglob('*.class'))}
(d/'resource-classes.json').write_text(json.dumps(manifest,indent=2)+'\n')
for arm in ['base','depth','resource','both']:
 cp=(old/('cp-depth.txt' if arm in ('depth','both') else 'cp-base.txt')).read_text().strip().split(':')
 assert cp.count(str(old/'harness'))==1
 cp[cp.index(str(old/'harness'))]=str(d/'harness')
 if arm in ('resource','both'):cp.insert(1,str(dest))
 assert not any('record-cancellation/layer' in x or 'resource-restoration/layer' in x or 'grouped-fix/classes' in x for x in cp)
 (d/f'cp-{arm}.txt').write_text(':'.join(cp)+'\n')
print('Frozen resource layer and four classpaths. Harness compile and exact source IDs still required.')
